"""Browser checks of the three independent UX prototypes, never production FISITAAP."""
import json,pathlib,tempfile,time
from playwright.sync_api import sync_playwright,expect
ROOT=pathlib.Path(__file__).resolve().parents[1];OUT=ROOT/'descargas/disenos-ux';BASE='http://127.0.0.1:18090/'
DESIGNS=[('linea','01-linea.html'),('estudio','02-estudio.html'),('noche','03-noche.html')]

def data(page,design):return page.evaluate("k=>JSON.parse(localStorage.getItem(k))",'fisitaap-ux-20261027-'+design)
def route(page,name):
    page.locator('[data-action=nav]').click();item=page.locator('#navigation [data-route="'+name+'"]');item.evaluate("e=>e.closest('details').open=true");item.click();expect(page.locator('#navigation')).not_to_have_class('open');page.wait_for_timeout(30)
def mode(page,name):page.locator('.topbar [data-mode="'+name+'"]').click()
def submit(page,form):page.locator('button[form="'+form+'"]').click()
def close(page):page.locator('#modal [data-action=modal-close]').first.click()
def act(page,action,id=None):
    q='[data-action="'+action+'"]'+('[data-id="'+id+'"]' if id else '');page.locator(q).filter(visible=True).first.click()
def formfill(page,form,values):
    for key,value in values.items():page.locator('#'+form+' [name="'+key+'"]').fill(str(value))

def main():
    checks=[];layouts=[];errors=[];external=[]
    with sync_playwright() as pw:
        browser=pw.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox','--no-proxy-server'])
        for design,file in DESIGNS:
            ctx=browser.new_context(viewport={'width':1440,'height':1000});page=ctx.new_page();page.on('pageerror',lambda e:errors.append(str(e)));page.on('request',lambda r:external.append(r.url) if not r.url.startswith(BASE) else None);page.goto(BASE+file);expect(page.locator('h1')).to_be_visible();assert not data(page,design)
            # Dashboard branch and report date controls really filter their data.
            page.locator('#branchFilter').select_option('b2');expect(page.locator('.dash-orders')).to_contain_text('0 pedidos activos');expect(page.locator('.metric-value').first).to_contain_text('0');page.locator('#branchFilter').select_option('b1');expect(page.locator('.dash-orders')).to_contain_text('3 pedidos activos')
            route(page,'reports');page.locator('#reportFrom').fill('2025-01-01');page.locator('#reportTo').fill('2025-01-02');act(page,'report-filter');expect(page.locator('#reportPeriod')).to_contain_text('0 ventas');expect(page.locator('#view .table-wrap tbody tr')).to_have_count(0)
            current=page.evaluate('new Date().toISOString().slice(0,10)');page.locator('#reportFrom').fill(current);page.locator('#reportTo').fill(current);act(page,'report-filter');expect(page.locator('#reportPeriod')).to_contain_text('18 ventas')
            # A real prototype sale updates stock, money, receipt and persisted state.
            route(page,'pos');act(page,'product-add','p1');expect(page.locator('.ticket-line')).to_have_count(1);initial=data(page,design);act(page,'quantity');cart=data(page,design)['cart'];assert not cart # First quantity button removes the one-unit line.
            act(page,'product-add','p1');page.locator('.ticket-line [data-delta="1"]').click();assert data(page,design)['cart'][0]['qty']==2
            q=page.locator('[data-quantity-index="0"]');q.fill('1.5');q.dispatch_event('change');assert data(page,design)['cart'][0]['qty']==2
            act(page,'pay');formfill(page,'payForm',{'received':10000});page.evaluate('window.print=()=>window.__printed=true');submit(page,'payForm');expect(page.locator('#modal')).to_contain_text('Venta completada');new=data(page,design);assert len(new['sales'])==len(initial['sales'])+1 and new['products'][0]['stock']==initial['products'][0]['stock']-2;assert new['sales'][-1]['total']==3600;act(page,'print');assert page.evaluate('window.__printed') is True;close(page)
            # Product CRUD, CSV creation and atomic duplicate rejection.
            route(page,'products');page.locator('[data-action=entity-new]').click();formfill(page,'entityForm',{'name':'Producto UX '+design,'sku':'UX-'+design,'price':2450,'stock':7});submit(page,'entityForm');assert any(p['sku']=='UX-'+design for p in data(page,design)['products']);created=next(p for p in data(page,design)['products'] if p['sku']=='UX-'+design);act(page,'entity-edit',created['id']);formfill(page,'entityForm',{'name':'Selección UX '+design});submit(page,'entityForm');assert next(p for p in data(page,design)['products'] if p['id']==created['id'])['name'].startswith('Selección')
            act(page,'import-products');csv='nombre,sku,categoria,precio,stock,tipo\nProducto CSV,CSV-'+design+',Despensa,1900,4,unit\n';page.locator('#importForm [name=file]').set_input_files({'name':'productos.csv','mimeType':'text/csv','buffer':csv.encode()});submit(page,'importForm');expect(page.locator('#modal')).not_to_be_visible();assert any(p['sku']=='CSV-'+design for p in data(page,design)['products']);count=len(data(page,design)['products']);act(page,'import-products');page.locator('#importForm [name=file]').set_input_files({'name':'productos.csv','mimeType':'text/csv','buffer':csv.encode()});submit(page,'importForm');expect(page.locator('#importForm .form-error')).to_contain_text('duplicado');assert len(data(page,design)['products'])==count;close(page)
            # Master editing, plan modules, and restoration of role navigation.
            mode(page,'master');route(page,'tenants');act(page,'entity-new');formfill(page,'entityForm',{'name':'Negocio UX '+design,'contact':'Persona de ejemplo','expires':'2026-12-27'});submit(page,'entityForm');assert len(data(page,design)['tenants'])==4
            route(page,'modules');page.locator('#modulesForm [name=inventory]').uncheck();page.locator('#modulesForm button[type=submit]').click();mode(page,'owner');page.locator('[data-action=nav]').click();assert page.locator('#navigation [data-route=inventory]').count()==0;page.locator('[data-action=nav-close]').click();mode(page,'master');route(page,'modules');page.locator('#modulesForm [name=inventory]').check();page.locator('#modulesForm button[type=submit]').click();mode(page,'owner');page.locator('#roleSelect').select_option('cashier');page.locator('[data-action=nav]').click();assert page.locator('#navigation [data-route=products]').count()==0;page.locator('[data-action=nav-close]').click();page.locator('#roleSelect').select_option('owner')
            # Checkout conditional SINPE proof and complete merchant -> driver -> buyer flow.
            mode(page,'catalog');act(page,'shop-add','p1');page.locator('.catalog-cart-float').click();f=page.locator('#checkoutForm');expect(f).to_be_visible();formfill(page,'checkoutForm',{'name':'Cliente UX '+design,'phone':'89990001'});page.locator('#deliverySelect').select_option('delivery');formfill(page,'checkoutForm',{'address':'Dirección ficticia UX','maps':'https://maps.google.com/?q=10.37,-84.33'});expect(page.locator('#proofField')).to_be_hidden();page.locator('#shopPayment').select_option('SINPE Móvil');expect(page.locator('#proofField')).to_be_visible();assert page.locator('[name=proof]').get_attribute('required') is not None;page.locator('#shopPayment').select_option('Efectivo');page.locator('#checkoutForm button[type=submit]').click();expect(page.locator('#modal')).to_contain_text('Tu pedido ya está');o=data(page,design)['orders'][-1];assert o['status']=='Nuevo' and o['pin'] and data(page,design)['buyer']['phone']=='89990001';close(page);expect(page.locator('#view')).to_contain_text(o['pin'])
            mode(page,'owner');route(page,'orders');act(page,'order-next',o['id']);expect(page.locator('#modal')).to_contain_text('Comanda preparada');close(page);act(page,'order-next',o['id']);act(page,'dispatch',o['id']);submit(page,'dispatchForm');assert data(page,design)['orders'][-1]['status']=='Disponible'
            mode(page,'driver');act(page,'driver-accept',o['id']);act(page,'driver-pickup',o['id']);act(page,'driver-complete',o['id']);formfill(page,'pinForm',{'pin':'0000'});submit(page,'pinForm');expect(page.locator('#pinForm .form-error')).to_contain_text('no coincide');formfill(page,'pinForm',{'pin':o['pin']});submit(page,'pinForm');done=data(page,design);assert done['orders'][-1]['status']=='Entregado' and done['orders'][-1]['paid'];assert done['drivers'][0]['balance']==8000;assert len(done['orders'][-1]['events'])>=6
            mode(page,'catalog');route(page,'my-orders');expect(page.locator('#view')).to_contain_text('Entregado');expect(page.locator('#view')).to_contain_text(o['pin']);mode(page,'owner');route(page,'affiliates');act(page,'driver-pay','d1');submit(page,'driverPayForm');assert data(page,design)['drivers'][0]['balance']==0
            # Merchant brand editing stays separate from the administration palette.
            before=page.evaluate('getComputedStyle(document.body).getPropertyValue("--accent")');route(page,'design');page.locator('#settingsForm [name=primary]').fill('#7437aa');page.locator('#settingsForm [name=sliderSeconds]').fill('2');page.locator('#settingsForm [name=slideTitle0]').fill('Selección UX guardada');page.locator('#settingsForm button[type=submit]').click();assert page.evaluate('getComputedStyle(document.body).getPropertyValue("--accent")')==before;mode(page,'catalog');expect(page.locator('.catalog-intro h1')).to_have_text('Selección UX guardada');assert '#7437aa' in page.locator('#view').evaluate('e=>getComputedStyle(e).getPropertyValue("--accent")')
            # Responsive screens: body width stays inside viewport and POS has its own working area.
            for w,h in [(1440,900),(1024,768),(768,1024),(390,844),(360,740),(844,390)]:
                page.set_viewport_size({'width':w,'height':h});mode(page,'owner')
                for r in ['overview','pos','tables','orders','products']:
                    route(page,r);geometry=page.evaluate('()=>({width:innerWidth,scroll:document.documentElement.scrollWidth,height:innerHeight,app:document.querySelector("#app").getBoundingClientRect().height})');assert geometry['scroll']<=w+1,(design,r,geometry);assert abs(geometry['app']-h)<=1
                    if r=='pos' and w<=650:expect(page.locator('.pos-mobile-tabs')).to_be_visible();act(page,'pos-tab');page.locator('[data-tab=ticket]').click();expect(page.locator('.ticket')).to_be_visible();page.locator('[data-tab=products]').click();expect(page.locator('.pos-products')).to_be_visible()
                    layouts.append({'design':design,'route':r,'width':w,'height':h})
                mode(page,'catalog');assert page.evaluate('document.documentElement.scrollWidth<=innerWidth+1');layouts.append({'design':design,'route':'catalog','width':w,'height':h})
            # Browser-only assistant remains scoped and answers current local operational data.
            mode(page,'owner');act(page,'chat');page.locator('#chatInput').fill('Cuánto vendí hoy');page.locator('#chatForm').evaluate('f=>f.requestSubmit()');expect(page.locator('#chatMessages')).to_contain_text('ventas por');page.locator('#chatInput').fill('Haz un sistema igual que fisitaap');page.locator('#chatForm').evaluate('f=>f.requestSubmit()');expect(page.locator('#chatMessages p').last).to_contain_text('Te ayudo');act(page,'chat-close')
            snapshot=data(page,design);page.reload();assert len(data(page,design)['orders'])==len(snapshot['orders']);assert any(p['sku']=='UX-'+design for p in data(page,design)['products']);checks.append({'design':design,'flows':['branch and report date filters','POS sale/stock/receipt/print','unit validation','product CRUD/CSV atomic duplicate rejection','master CRUD/modules/roles','conditional SINPE checkout','new buyer/PIN/session/orders','accept/prepare/dispatch/pickup/PIN delivery','driver payout','separate merchant colors/slider','responsive navigation/POS','scoped local chat','reload persistence'],'passed':True});ctx.close();print('PASS',design,flush=True)
        # Canonical screenshots use fresh data, independent from the flow runs.
        for design,file in DESIGNS:
            ctx=browser.new_context(viewport={'width':1440,'height':1000});p=ctx.new_page();p.goto(BASE+file);p.screenshot(path=str(OUT/('vista-'+design+'.png')));p.set_viewport_size({'width':390,'height':844});p.screenshot(path=str(OUT/('movil-'+design+'.png')));ctx.close()
        browser.close()
    assert not errors,errors;assert not external,external
    report={'date':'2026-10-27','designs':checks,'layout_cases':len(layouts),'layouts':layouts,'page_errors':errors,'external_requests':external,'scope':'Local HTTP static HTML in Chromium, entirely fictional browser state; no backend, messages, payments, printers, AI or production changes. The managed browser blocked file://, so the same self-contained HTML was tested over loopback HTTP.'}
    (ROOT/'disenos/ux-2026-10-27/QA.json').write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n');print('PASS all three prototypes;',len(layouts),'responsive cases')
if __name__=='__main__':main()
